# Мои задачи и финансы — этап 2: меню и учёт расходов
print("1 — калькулятор")
print("2 — расходы")
choice = input("Выбор: ")
if choice == "1":
    a = float(input("Первое число: "))
    op = input("Действие (+ - * /): ")
    b = float(input("Второе число: "))
    if op == "+":
        print("Результат:", round(a + b, 2))
    elif op == "-":
        print("Результат:", round(a - b, 2))
    elif op == "*":
        print("Результат:", round(a * b, 2))
    elif op == "/":
        if b == 0:
            print("На ноль делить нельзя")
        else:
            print("Результат:", round(a / b, 2))
    else:
        print("Неизвестное действие")
elif choice == "2":
    expenses = []
    while True:
        line = input("Сумма (пусто — конец): ")
        if line == "":
            break
        expenses.append(float(line))
    if len(expenses) == 0:
        print("Расходов нет")
    else:
        print("Покупок:", len(expenses))
        print("Всего:", round(sum(expenses), 2))
        print("Самая крупная:", max(expenses))
        print("В среднем:", round(sum(expenses) / len(expenses), 2))
else:
    print("Нет такого пункта")

